import { AdvanceOrderUseCase } from '../../application/use-cases/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../../application/use-cases/CancelOrderUseCase';
import { GetOrderUseCase } from '../../application/use-cases/GetOrderUseCase';
import { ListOrdersByStateUseCase } from '../../application/use-cases/ListOrdersByStateUseCase';
import { PlaceOrderUseCase } from '../../application/use-cases/PlaceOrderUseCase';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { StockReservationService } from '../../domain/services/StockReservationService';
import { OrderController } from '../http/OrderController';

/** Wires the order use cases into the order controller. */
export function buildOrderController(orders: OrderRepository, stock: StockReservationService): OrderController {
  return new OrderController({
    placeOrder: new PlaceOrderUseCase(orders, stock),
    getOrder: new GetOrderUseCase(orders),
    listOrdersByState: new ListOrdersByStateUseCase(orders),
    advanceOrder: new AdvanceOrderUseCase(orders),
    cancelOrder: new CancelOrderUseCase(orders, stock),
  });
}

